@startuml

class RepairShop {
  + Name : string
  + Address : string
  + NumberOfEmployees : int
}

class Employee {
  + TaxCode : string
  + Address : string
  + PhoneNumber : string
  + YearsOfService : int
}

class Director extends Employee {
  + Age : int
}

class Repair {
  + Code : string
  + CheckInDateTime : datetime
  + ReturnDateTime : datetime
}

class Vehicle {
  + Model : string
  + Type : string
  + LicensePlate : string
  + YearOfRegistration : int
}

class Owner {
  + TaxCode : string
  + Address : string
  + PhoneNumber : string
}

class Customer {
  + TaxCode : string
  + Address : string
  + PhoneNumber : string
}

RepairShop "1" -- "*" Employee
RepairShop "1" -- "1" Director : manages
RepairShop "1" -- "*" Repair
Repair "1" -- "1" Vehicle
Vehicle "1" -- "1" Owner
Owner "1" -- "0..*" Vehicle
Customer "1" -- "*" Vehicle
Customer "1" -- "*" Repair

@enduml

